create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,occurred_at timestamptz not null default now(),before_data jsonb,after_data jsonb,metadata jsonb not null default '{}'::jsonb);
create index if not exists idx_audit_logs_actor_time on public.audit_logs(actor_id,occurred_at desc); create index if not exists idx_audit_logs_entity_time on public.audit_logs(entity_type,entity_id,occurred_at desc); create index if not exists idx_audit_logs_action_time on public.audit_logs(action,occurred_at desc);
alter table public.audit_logs enable row level security; drop policy if exists audit_logs_admin_read on public.audit_logs; create policy audit_logs_admin_read on public.audit_logs for select to authenticated using(public.is_admin()); revoke insert,update,delete on public.audit_logs from anon,authenticated; grant select on public.audit_logs to authenticated;
